const linkCraftCategoryToCatalog = `-- name: LinkCraftCategoryToCatalog :exec
WITH reference AS (
    SELECT id, slug, name, default_unit, sort_order, workspace_id, catalog_slug, fields FROM craft_categories r
    WHERE r.workspace_id IS NULL AND r.slug = $2::text
), linked AS (
    UPDATE craft_categories c
    SET catalog_slug = reference.slug
    FROM reference
    WHERE c.workspace_id = $1::uuid
      AND c.catalog_slug = ''
      AND (c.slug = reference.slug OR lower(c.name) = lower(reference.name))
      AND NOT EXISTS (
          SELECT 1 FROM craft_categories other
          WHERE other.workspace_id = $1::uuid AND other.catalog_slug = reference.slug
      )
    RETURNING c.id
)
INSERT INTO craft_categories (workspace_id, slug, name, default_unit, sort_order, catalog_slug)
SELECT $1::uuid, slug, name, default_unit, sort_order, slug
FROM reference
WHERE NOT EXISTS (SELECT 1 FROM linked)
ON CONFLICT DO NOTHING
`

